---RefreshUI
---刷新UI
--- 传入的 colorVertex1 与 colorVertex2 优先级最高
--- 道具标题 传 rare
---@param title string                 标题名称
---@param rare Constants.QualityType   品质类型
---@param iconPath string | nil        图标
function CommonTitleNode:RefreshUI(title, rare, customBgColor, customTextColor, isDisableTextColor, iconPath)
    self.Text.text = tostring(title)
    self.imageComp.color = XLuaUtils.HexToColor("#ffffff")
    
    local colorKeys = {}
    if rare == Constants.QualityType.Colours then
        for i, color in ipairs(ColoursColor) do
            local location = ColoursLocation[i]
            table.insert(colorKeys, GradientColorKey(XLuaUtils.HexToColor(color), location))
        end
    else
        local color     = self:GetTitleBgColor(rare)
        
        local tempColor = XLuaUtils.HexToColor(customBgColor or color)
        table.insert(colorKeys, GradientColorKey(tempColor, 0))
    end
    
    local alphaKeys = {GradientAlphaKey(180/255, Time1), GradientAlphaKey(97/255, Time2), GradientAlphaKey(0, Time3)}
    --self.Bg.EffectGradient:SetKeys(colorKeys, alphaKeys)

    if not isDisableTextColor then
        local textColor = self:GetTitleTextColor(rare)
        self.Text.color = XLuaUtils.HexToColor(customTextColor or textColor)
    end

    if iconPath then
        CfUtils.SetActive(self.Attribute, true)
        CfUtils.FillImage(self.ImgAttributeIcon, iconPath)
    else
        CfUtils.SetActive(self.Attribute, false)
    end
end

