function CommonTitleNode:GetTitleBgColor(rare)
    return BackgroundColors[checkInt(rare)] or BackgroundColors[1]
end

function CommonTitleNode:GetTitleTextColor(rare)
    return TextColors[checkInt(rare)] or "7b7a7a"
end

